import{c as a,Q as t,j as e,m as i}from"./chunks/framework.t4rEqR7d.js";const k=JSON.parse('{"title":"VS Code 插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/vscode.md","filePath":"zh/vscode.md"}'),n={name:"zh/vscode.md"};function d(p,s,o,l,h,r){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="vs-code-插件" tabindex="-1">VS Code 插件 <a class="header-anchor" href="#vs-code-插件" aria-label="Permalink to &quot;VS Code 插件&quot;">​</a></h1><p>语言：中文 | <a href="/pagent/vscode.html">English</a></p><p>pagent VS Code 插件会在 VS Code 里提供一个聊天面板。你安装插件后，可以直接在侧边栏和 pagent 对话，让它在当前工作区里执行文件读取、命令运行、工具调用和会话恢复等操作。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>先从 <a href="https://github.com/SyncLionPaw/pagent/releases" target="_blank" rel="noreferrer">pagent GitHub Releases</a> 下载 VS Code 插件包：</p><p>下载文件名以 <code>.vsix</code> 结尾的插件文件。</p><p>在 VS Code 里安装：</p><ol><li>打开 VS Code 左侧 <strong>Extensions</strong> 面板。</li><li>点击 Extensions 面板右上角的 <code>...</code> 菜单。</li><li>选择 <strong>Install from VSIX...</strong>。</li><li>选择刚下载的 <code>.vsix</code> 文件。</li><li>安装完成后，重新加载窗口；左侧活动栏会出现 pagent 图标。</li></ol><p>也可以打开命令面板，运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extensions: Install from VSIX...</span></span></code></pre></div><p>插件还需要本机能运行 <code>pagent</code> 命令。先安装 CLI：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pagent</span></span></code></pre></div><p>如果 VS Code 提示找不到 <code>pagent</code>，可以在设置里把 <code>pagent.command</code> 改成 <code>pagent</code> 可执行文件的绝对路径。</p><h2 id="第一次打开" tabindex="-1">第一次打开 <a class="header-anchor" href="#第一次打开" aria-label="Permalink to &quot;第一次打开&quot;">​</a></h2><p>点击左侧 pagent 图标，打开 <strong>Chat</strong>。</p><p>如果还没有配置过 API Key，插件会弹出输入框，引导你填写：</p><ul><li>API Key</li><li>模型名称，默认是 <code>deepseek-v4-flash</code></li><li>Base URL，可留空</li></ul><p>保存后，插件会写入 <code>pagent.toml</code>，然后即可开始对话。</p><p><a href="/pagent/zh/desktop.html">桌面端</a> <strong>没有</strong>这套引导，需事先配置 <code>pagent.toml</code> 或 <code>DEEPSEEK_API_KEY</code>。</p><h2 id="插件会创建哪些文件" tabindex="-1">插件会创建哪些文件 <a class="header-anchor" href="#插件会创建哪些文件" aria-label="Permalink to &quot;插件会创建哪些文件&quot;">​</a></h2><p>插件会使用一个 pagent home 目录保存配置、会话和本地 skills。</p><p>如果当前工作区已经有 <code>.pagent/</code> 目录，插件会使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;workspace&gt;/.pagent/</span></span></code></pre></div><p>如果当前工作区没有 <code>.pagent/</code>，插件会使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.pagent/</span></span></code></pre></div><p>如果你希望某个项目使用独立配置和独立会话历史，可以在项目根目录手动创建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .pagent</span></span></code></pre></div><p>之后插件会使用这个项目下的 <code>.pagent/</code>。</p><p>常见文件如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.pagent/</span></span>
<span class="line"><span>├── pagent.toml          # 配置文件，保存模型、API Key、sandbox 等配置</span></span>
<span class="line"><span>├── threads/             # 会话历史</span></span>
<span class="line"><span>│   └── thread-.../</span></span>
<span class="line"><span>│       ├── metainfo.json</span></span>
<span class="line"><span>│       └── messages.jsonl</span></span>
<span class="line"><span>└── skills/              # 可选，本地 skills 目录</span></span></code></pre></div><p>这些文件的含义：</p><table tabindex="0"><thead><tr><th>路径</th><th>保存内容</th></tr></thead><tbody><tr><td><code>pagent.toml</code></td><td>模型、API Key、Base URL、运行模式、SSH、审批模式等配置</td></tr><tr><td><code>threads/</code></td><td>会话历史，每个 thread 是一次可恢复的对话</td></tr><tr><td><code>metainfo.json</code></td><td>thread 的标题、创建时间、更新时间、消息数量</td></tr><tr><td><code>messages.jsonl</code></td><td>该 thread 的消息内容</td></tr><tr><td><code>skills/</code></td><td>可选，本地 skills</td></tr></tbody></table><p>没有消息的空 thread 会在后端正常退出时自动清理。</p><p>如果 <code>.pagent/</code> 放在项目目录里，并且项目会提交到 Git，请避免提交包含 API Key 的 <code>pagent.toml</code>。</p><h2 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h2><p>插件第一次配置 API Key 后，会写入 <code>pagent.toml</code>。也可以手动编辑：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-v4-flash&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># base_url = &quot;https://...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sandbox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;local&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # local | docker | podman | ssh</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">command_policy = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workdir&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/.ssh/config&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-remote&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">workdir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/pagent&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prompt&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # prompt | auto</span></span></code></pre></div><p>也可以通过环境变量提供 API Key：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span></code></pre></div><h2 id="怎么使用" tabindex="-1">怎么使用 <a class="header-anchor" href="#怎么使用" aria-label="Permalink to &quot;怎么使用&quot;">​</a></h2><p>打开 Chat 后，直接在底部输入框输入问题，回车发送。<code>Shift+Enter</code> 换行。</p><p>插件会流式显示回复。模型的思考过程会显示在可折叠的 <code>thinking</code> 面板里。工具调用会显示成工具卡片，你可以展开查看细节。</p><h2 id="标题栏按钮" tabindex="-1">标题栏按钮 <a class="header-anchor" href="#标题栏按钮" aria-label="Permalink to &quot;标题栏按钮&quot;">​</a></h2><p>Chat 视图右上角有三个按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td>在编辑器区打开</td><td>打开一个更宽的聊天面板</td></tr><tr><td>恢复会话</td><td>从历史会话中选择一个继续</td></tr><tr><td>新会话</td><td>开始一个新的空会话</td></tr></tbody></table><h2 id="输入框按钮" tabindex="-1">输入框按钮 <a class="header-anchor" href="#输入框按钮" aria-label="Permalink to &quot;输入框按钮&quot;">​</a></h2><p>输入框下方有几个按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td><code>/</code></td><td>打开斜杠命令菜单</td></tr><tr><td>运行模式</td><td>选择工具运行在哪里</td></tr><tr><td>盖章</td><td>开启或关闭 YOLO 模式</td></tr><tr><td>发送</td><td>发送当前输入</td></tr></tbody></table><p>YOLO 模式会自动批准危险工具调用，例如运行命令。只在你信任当前工作区和当前请求时开启。</p><h2 id="运行模式" tabindex="-1">运行模式 <a class="header-anchor" href="#运行模式" aria-label="Permalink to &quot;运行模式&quot;">​</a></h2><p>运行模式决定 pagent 的工具在哪里执行。</p><table tabindex="0"><thead><tr><th>模式</th><th>含义</th></tr></thead><tbody><tr><td>Local</td><td>在当前电脑上执行工具</td></tr><tr><td>Docker</td><td>在 Docker 容器里执行工具</td></tr><tr><td>Podman</td><td>在 Podman 容器里执行工具</td></tr><tr><td>SSH</td><td>在远程机器上执行工具</td></tr></tbody></table><p>Docker 和 Podman 选项只有在 VS Code 所在环境能找到对应命令时才显示。</p><p>SSH 模式会读取 <code>~/.ssh/config</code>，展示里面明确写出的 <code>Host</code> 别名。<code>Host *</code> 这类通配项不会出现在菜单里。</p><h2 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h2><p>点击 <code>/</code> 按钮，或在输入框里输入 <code>/</code>，可以打开命令菜单。</p><p>当前支持：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/help</code></td><td>查看可用命令</td></tr><tr><td><code>/skills</code></td><td>查看已加载的 skills</td></tr><tr><td><code>/history</code></td><td>查看会话信息</td></tr><tr><td><code>/pwd</code></td><td>查看当前 pagent home / 工作区上下文</td></tr><tr><td><code>/ls</code></td><td>列出当前上下文中的文件</td></tr></tbody></table><p>斜杠命令不会触发模型对话，也不会写入会话历史。</p><h2 id="工具审批" tabindex="-1">工具审批 <a class="header-anchor" href="#工具审批" aria-label="Permalink to &quot;工具审批&quot;">​</a></h2><p>默认情况下，危险工具会先暂停，等待你批准。你会在工具卡片里看到批准和拒绝按钮。</p><p>如果开启 YOLO 模式，审批会自动通过。也可以在配置里写：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>安装后左侧没有 pagent 图标。</strong></p><p>确认 <code>.vsix</code> 已安装成功，并重新加载 VS Code 窗口。</p><p><strong>提示找不到 <code>pagent</code>。</strong></p><p>先执行 <code>uv tool install pagent</code>。如果仍然找不到，在 VS Code 设置里修改 <code>pagent.command</code>。</p><p><strong>Docker 或 Podman 没有出现在菜单里。</strong></p><p>当前 VS Code 环境里没有对应 CLI，或 CLI 不在 PATH 里。</p><p><strong>SSH Host 没有出现。</strong></p><p>检查 <code>pagent.sshConfigPath</code> 指向的文件，并确认里面有明确的 <code>Host xxx</code> 配置。</p><p><strong>会话历史在哪里。</strong></p><p>在当前 pagent home 的 <code>threads/</code> 目录下。项目模式通常是 <code>&lt;workspace&gt;/.pagent/threads/</code>，否则是 <code>~/.pagent/threads/</code>。</p>`,74)])])}const g=a(n,[["render",d]]);export{k as __pageData,g as default};
